// Сгенерировано kb.py — не править руками
export const KB = [{"d":"Устав ВС и ФСВНГ","t":"Статья 1.1. Соблюдение Устава","x":"Каждый военнослужащий обязан знать и соблюдать положения настоящего Устава. Незнание Устава не освобождает от ответственности.","r":"ВУ ст. 1.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.2. Воинский долг","x":"Каждый военнослужащий обязан честно и качественно исполнять воинский долг, защищать национальные интересы, суверенитет и целостность территории Российской Федерации.","r":"ВУ ст. 1.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.3. Исполнение приказов","x":"Военнослужащий обязан исполнить законный приказ начальника. При получении заведомо незаконного приказа военнослужащий не исполняет его и незамедлительно докладывает непосредственному либо вышестоящему начальнику.","r":"ВУ ст. 1.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.4. Репутация Армии","x":"Запрещены действия, способные нанести ущерб репутации Армии или подорвать доверие к ней.","r":"ВУ ст. 1.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.5. Обращение по служебным вопросам","x":"При возникновении служебных вопросов военнослужащий обращается к командиру своего подразделения.","r":"ВУ ст. 1.5"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.6. Единоначалие","x":"Командир наделен распорядительной властью и несет персональную ответственность за подразделение.","r":"ВУ ст. 1.6"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.7. Построения","x":"Во время объявленного построения военнослужащие обязаны явиться в назначенное место точно и в срок, кроме лиц, несущих службу на посту.","r":"ВУ ст. 1.7"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.8. Набор","x":"Набор в ряды Армии осуществляется посредством агитационных мероприятий и призывов по утвержденному графику.","r":"ВУ ст. 1.8"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.9. КМБ и Военная академия","x":"Курс молодого бойца проходит не более чем за 5 дней, Военная академия - не более чем за 10 дней. После провала Военной академии военнослужащий заносится в черный список на срок от 14 до 90 дней по решению командования.","r":"ВУ ст. 1.9"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.10. Основания для увольнения","x":"Основаниями для увольнения являются: собственное желание; грубое нарушение Устава; нарушение законодательства; решение суда или предписание Прокуратуры; непрохождение КМБ или Военной академии; отсутствие в подразделении более 48 часов; нахождение в части без формы; самовольное оставление части; иные прямо предусмотренные настоящим Уставом основания. Наличие дисциплинарных взысканий влечет последствия в порядке, установленном Дисциплинарным уставом.","r":"ВУ ст. 1.10"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.11. Военная присяга","x":"Каждый военнослужащий, прибывший в часть и проходящий КМБ или Военную академию, обязан принять Военную присягу. Отказ от ее принятия или грубое нарушение присяги является основанием для увольнения.","r":"ВУ ст. 1.11"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.12. Сбережение имущества","x":"Военнослужащий обязан бережно относиться к вооружению, технике, обмундированию и иному государственному имуществу. Запрещены умышленная порча, неаккуратное использование служебного транспорта, утрата или небрежное хранение оружия и спецсредств, использование казенного имущества в личных целях.","r":"ВУ ст. 1.12"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.1. Служебный день","x":"Рабочий день для личного состава ВС и ФСВНГ устанавливается ежедневно с 11:00 до 21:30.","r":"ВУ ст. 2.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.2. Перерыв","x":"Обеденное время устанавливается ежедневно с 18:00 до 19:00 и предоставляется без оформления увольнительной.","r":"ВУ ст. 2.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.3. Вызов на службу","x":"Служебная деятельность не прекращается после завершения рабочего дня. Военнослужащий может быть вызван из отгула, кроме отпуска в мирное время.","r":"ВУ ст. 2.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.4. Вечерняя проверка","x":"Ежедневно в 21:00 проводится вечерняя проверка. Во время вечерней проверки постовые не покидают пост. Их присутствие подтверждается докладом по рации, через начальника караула либо после смены поста.","r":"ВУ ст. 2.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.5. Изменение графика","x":"Командир части вправе временно корректировать график приказом.","r":"ВУ ст. 2.5"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.6. Увольнительное время и выход из части","x":"Рядовой и ефрейтор могут покидать часть только по увольнительной, при наличии необходимых и непереносимых для увольнительной причин. Начиная со звания младший сержант, военнослужащий вправе запросить и получить увольнительное время продолжительностью 60 минут в день (можно разбить на два промежутка длительностью 30 минут). Младший сержант и выше могут покидать часть после окончания службы при отсутствии ограничений, наряда, тревоги или дисциплинарного запрета.","r":"ВУ ст. 2.6"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.7. Отпуск","x":"Младший сержант и выше имеют право на отпуск до 7 дней раз в месяц. По семейным обстоятельствам отпуск может быть предоставлен в ином объеме по решению вышестоящего командования.","r":"ВУ ст. 2.7"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.8. Отдых в части","x":"Для отдыха на территории части используются казарма, раздевалка и медицинский блок. Продолжительность отдыха не должна препятствовать службе.","r":"ВУ ст. 2.8"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.9. Повышенная готовность","x":"При переходе в режим повышенной боевой готовности (Код-4) часть переходит в круглосуточный режим, весь состав находится в расположении части.","r":"ВУ ст. 2.9"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.10. Плановый медицинский осмотр","x":"Плановый медицинский осмотр проводится до вечерней проверки либо после замены военнослужащего на посту. Он проводится в независимое от вечерней проверки время и назначается сотрудниками медицинской роты.","r":"ВУ ст. 2.10"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.1. Военная форма","x":"В расположении части и на официальных мероприятиях обязательна военная форма. Форма должна соответствовать подразделению и воинскому званию.","r":"ВУ ст. 3.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.2. Внешний вид и форма одежды","x":"Запрещаются спортивная и пляжная одежда, неопрятная одежда, яркие аксессуары, неустановленные знаки различия, криминальная или аморальная символика. Требования к прическе, бороде и усам устанавливаются настоящим Уставом и приказами командования.","r":"ВУ ст. 3.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.3. Требования к внешнему виду военнослужащих","x":"Новобранцы до присвоения звания младшего сержанта обязаны иметь полностью выбритую голову и не допускаются к службе при наличии растительности на лице. Начиная со звания младшего сержанта, прическа военнослужащего должна быть аккуратной, соответствовать требованиям гигиены и не препятствовать ношению головных уборов, средств индивидуальной защиты, включая каску и противогаз.","r":"ВУ ст. 3.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.4. Обращение с оружием","x":"Военнослужащий обязан относиться к оружию как к заряженному, не направлять его на людей без непосредственной необходимости, не держать палец на спусковом крючке до принятия решения о выстреле и быть уверенным в цели и обстановке за ней.","r":"ВУ ст. 3.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.4.1. Право на ношение табельного оружия","x":"Постоянное ношение табельного оружия при исполнении служебных обязанностей допускается всеми военнослужащими, наличие такого обязательно на период фактического несения караульно-постовой службы, патрулирования, учений, тренировок, специальных операций либо иной служебной деятельности.","r":"ВУ ст. 3.4.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.4.2. Сдача вооружения при выходе из части","x":"Военнослужащие в звании от рядового до подполковника включительно, покидающие территорию воинской части в гражданской форме, обязаны до выхода через контрольно-пропускной пункт сдать закрепленные за ними оружие, боеприпасы и специальные средства на склад вооружения. Запрещается оставлять табельное оружие, боеприпасы и специальные средства в личном транспортном средстве либо передавать их другому лицу без законных оснований. Исключение: ношение вооружения по гражданской форме допускается для военнослужащих ССО, ГРУ и Военной полиции при выполнении служебной или оперативной задачи, прямо предполагающей ношение оружия за пределами воинской части.","r":"ВУ ст. 3.4.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.5. Бодикамеры","x":"Бодикамера обязательна для сотрудников ВП, ОСБ, военнослужащих на КПП, патрулей и лиц, проводящих задержание. При неисправности камеры военнослужащий докладывает старшему и фиксирует обстоятельства в журнале.","r":"ВУ ст. 3.5"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.1. Иерархия","x":"Иерархическая структура Армии: Лидер Армии; Заместитель Лидера Армии; Начальник ВС и его заместители; Начальник ФСВНГ и его заместители; командиры подразделений.","r":"ВУ ст. 4.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.2. Должностные лица","x":"Лидер Армии осуществляет общее руководство. Заместитель Лидера действует в пределах порученных полномочий. Начальники ВС и ФСВНГ организуют работу подчиненных структур. Командиры подразделений обеспечивают службу и дисциплину личного состава.","r":"ВУ ст. 4.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.3. Подразделения","x":"Военная полиция обеспечивает правопорядок и дисциплину. Медицинская рота оказывает медицинскую помощь. ГРУ, ССО, МСК, ОСБ, РВО, ОМОН, Военная академия и Военный комиссариат выполняют задачи в пределах своей компетенции и приказов командования.","r":"ВУ ст. 4.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.4. Зоны ответственности","x":"Армия охраняет территорию воинской части, военный комиссариат, полигон “Алабино” и иные объекты, закрепленные приказами командования. Охрана не предоставляет военнослужащим право самостоятельно назначать гражданским лицам наказание. Приложение: полномочия по взысканиям: Командир подразделения вправе объявить устное предупреждение или выговор. Начальник ВС, Начальник ФСВНГ и их заместители вправе объявить строгий выговор и инициировать служебную проверку. Понижение в должности и увольнение рассматриваются Лидером Армии или уполномоченным им должностным лицом по результатам проверки. Полный перечень мер и порядок их применения определяются Дисциплинарным уставом.","r":"ВУ ст. 4.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.4.1. Военный полигон “Алабино”","x":"Военный полигон “Алабино” является учебно-тренировочной и режимной территорией Армии, предназначенной для проведения тактических занятий, учений, тренировок подразделений, отработки действий личного состава, эксплуатации военной техники и иных мероприятий боевой подготовки. На территории полигона “Алабино” допускаются тренировки военнослужащих, передвижение и эксплуатация служебной военной техники, патрулирование и проведение учебных мероприятий при соблюдении требований безопасности, режима объекта и распоряжений командования. Самовольный выезд военной техники за пределы полигона “Алабино”, использование техники не по назначению, создание помех учебным мероприятиям, повреждение имущества или инфраструктуры полигона “Алабино” запрещаются. Порядок охраны полигона “Алабино”, перечень постов и правила патрулирования устанавливаются Уставом караульно-постовой службы.","r":"ВУ ст. 4.4.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.1. Субординация","x":"Субординация является системой иерархических отношений, уважения дисциплины и исполнения законных приказов.","r":"ВУ ст. 5.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.2. Воинское приветствие","x":"Военнослужащие обязаны соблюдать правила воинского приветствия, доклада и обращения к старшим по званию.","r":"ВУ ст. 5.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.3. Действия в отношении граждан","x":"Военнослужащие вправе пресекать незаконное проникновение на территорию режимного объекта, ограничивать доступ, задерживать лицо при законных основаниях и передавать его ВП, МВД либо иному компетентному органу. Самостоятельное назначение наказания гражданским лицам не допускается.","r":"ВУ ст. 5.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.4. Применение силы","x":"Сила допускается только при нападении, непосредственной угрозе жизни, попытке незаконного проникновения или законном задержании. После применения силы обязательно: медицинская помощь при необходимости, доклад, фиксация на камеру и рапорт.","r":"ВУ ст. 5.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 6.1. Теги подразделений","x":"В служебной связи используются утвержденные теги подразделений: ВП, МР, ГРУ, ССО, МСК, ВК, ОСБ, РВО, ОМОН и КС. Полковники и выше могут использовать связь без тэга в порядке, установленном командованием.","r":"ВУ ст. 6.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 6.2. Коды обстановки","x":"Код-1 означает спокойную обстановку; Код-2 - скопление подозрительных лиц или нарушение порядка; Код-3 - проникновение, вооруженное нападение или массовое нарушение; Код-4 - боевую тревогу.","r":"ВУ ст. 6.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.1.1. Специальные операции","x":"Основная задача при поставках и специальных операциях - загрузка и доставка груза без утрат и задержек. Запрещены действия, препятствующие безопасности операции.","r":"ВУ ст. 7.1.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.1.2. Реакция на стрельбу","x":"ССО, ГРУ и ОМОН являются основными подразделениями реагирования. При непосредственной угрозе жизни, нападении на пост или проникновении любой военнослужащий действует в пределах необходимой обороны, докладывает по рации и вызывает группу реагирования.","r":"ВУ ст. 7.1.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.2. Военное положение","x":"При объявлении военного положения весь состав действует по распоряжениям Лидера Армии и командования, использует боевую форму и занимает назначенные позиции.","r":"ВУ ст. 7.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.3. Код-3","x":"При объявлении Кода-3 военнослужащий получает обмундирование, докладывает местоположение, направление и приметы нарушителя, а при наличии транспорта - марку, модель, цвет и номер. Подразделения действуют в пределах компетенции и приказов старшего.","r":"ВУ ст. 7.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.4. Обязанности постового","x":"Постовой обязан бдительно нести службу, требовать документы, не покидать пост до прибытия смены, немедленно докладывать о нештатной ситуации и применять оружие только в предусмотренных случаях.","r":"ВУ ст. 7.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.5. Единый порядок инцидента","x":"При обнаружении нарушения военнослужащий докладывает по рации, фиксирует обстоятельства на бодикамеру, ограничивает доступ или пресекает угрозу в пределах полномочий, вызывает ВП или дежурного, передает лицо уполномоченному сотруднику и оформляет рапорт.","r":"ВУ ст. 7.5"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.1. Отчеты","x":"Отчеты подаются по утвержденной форме. При обнаружении ошибки создается новый отчет в порядке, установленном командованием.","r":"ВУ ст. 8.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.2. Повышения","x":"Для повышения не должно быть активных дисциплинарных взысканий. Повышение проводится по системе подразделения и по представлению командира, согласованному с вышестоящим командованием.","r":"ВУ ст. 8.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.2.5. Повышение военнослужащего на посту","x":"Военнослужащий, несущий службу на посту, проходит процедуру повышения после сдачи поста либо через представителя подразделения.","r":"ВУ ст. 8.2.5"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.3. Повторный инструктаж","x":"После нарушения правил оружия, КПП, связи или постовой службы военнослужащий до повторного допуска проходит инструктаж или проверку знаний. Инструктаж не заменяет дисциплинарное взыскание, если оно подлежит применению. Приложения:","r":"ВУ ст. 8.3"},{"d":"Дисциплинарный устав","t":"Статья 1. Сфера действия и иерархия норм","x":"Настоящий Устав устанавливает основы воинской дисциплины, порядок применения дисциплинарных мер и меры поощрения военнослужащих Вооружённых Сил и сотрудников ФСВНГ.","r":"ДУ ст. 1"},{"d":"Дисциплинарный устав","t":"Статья 2. Воинская дисциплина","x":"Воинская дисциплина основывается на сознательном исполнении обязанностей, соблюдении субординации, уважении к службе и достоинству других лиц, бережном отношении к имуществу и готовности действовать в интересах подразделения. Военнослужащий обязан соблюдать законодательство и уставы, исполнять законные приказы, поддерживать порядок, не допускать действий, подрывающих безопасность службы или авторитет ведомства.","r":"ДУ ст. 2"},{"d":"Дисциплинарный устав","t":"Статья 3. Ответственность командования","x":"Командир организует службу, поддерживает дисциплину, рассматривает сведения о нарушениях в пределах компетенции и принимает меры, соразмерные тяжести проступка. Командиру запрещается унижать подчинённых, применять неуставное физическое или психологическое воздействие, скрывать сведения о серьёзном нарушении либо преследовать военнослужащего за добросовестное обращение.","r":"ДУ ст. 3"},{"d":"Дисциплинарный устав","t":"Статья 4. Полномочия Военной полиции и ОСБ","x":"Военная полиция выявляет нарушения, самостоятельно рассматривает \\ выносит \\ решает вопросы по привлечению к ответственности военнослужащих, в том числе по вопросам административной, дисциплинарной, уголовной в соответствие с процессуальным законодательством, обеспечивает порядок на военных объектах и передаёт информацию о нарушениях уполномоченным должностным лицам. Военная полиция действует в рамках законодательства и уставов. При выявлении нарушения сотрудником ФСВНГ, включая РВО, Кадровую службу и ОМОН, Военная полиция передаёт материалы и сведения в ОСБ. Самостоятельно дисциплинарные взыскания сотрудникам ФСВНГ Военная полиция не назначает. При выявлении нарушения сотрудником ВС, ОСБ передаёт материалы и сведения в военную полицию. Самостоятельно дисциплинарные взыскания сотрудникам ВС ОСБ не назначает. ОСБ рассматривает полученную информацию, самостоятельно рассматривает \\ выносит \\ решает вопросы по привлечению к ответственности ФСВНГ, в том числе по вопросам административной, дисциплинарной, уголовной в соответствие с процессуальным законодательством, и действует в пределах своей компетенции. Решение о дисциплинарной ответственности принимается уполномоченным должностным лицом после проверки обстоятельств. ОСБ работает по нарушениям только внутри подразделений ФСВНГ.","r":"ДУ ст. 4"},{"d":"Дисциплинарный устав","t":"Статья 5. Принципы дисциплинарной ответственности","x":"Взыскание применяется за виновное нарушение и должно быть справедливым, соразмерным его характеру, последствиям, роли лица и обстоятельствам совершения. При назначении взыскания учитываются признание вины, содействие проверке, повторность, степень опасности нарушения и прежнее отношение военнослужащего к службе. За один проступок не может назначаться более одного дисциплинарного взыскания. Дисциплинарное взыскание не заменяет ответственность, установленную законодательством. При выборе меры учитываются тяжесть нарушения, последствия, степень вины, повторность и поведение военнослужащего. Взыскание должно быть адекватным и соразмерным проступку. Если статья предусматривает несколько возможных мер, уполномоченное лицо выбирает одну из них с учётом обстоятельств нарушения.","r":"ДУ ст. 5"},{"d":"Дисциплинарный устав","t":"Статья 6. Виды дисциплинарных взысканий","x":"К военнослужащему или сотруднику, признанному виновным в дисциплинарном проступке, в пределах компетенции могут применяться следующие меры: - беседа (устное предупреждение) - применяется за малозначительное нарушение и не вносится в планшет; - устный выговор - применяется за нарушение средней тяжести и учитывается в планшете как один активный выговор; - строгий выговор - применяется за грубое, повторное либо создавшее угрозу нарушение и учитывается в планшете как два активных выговора; - понижение в должности или звании - только уполномоченным руководителем в порядке, установленном внутренними актами; - увольнение со службы - применяется за наиболее тяжкие нарушения, грубую повторность либо накопление активных выговоров; оформляется уполномоченным руководителем после рассмотрения материалов проверки.","r":"ДУ ст. 6"},{"d":"Дисциплинарный устав","t":"Статья 6.1. Учёт и отработка активных выговоров","x":"Устный выговор учитывается в планшете как один активный выговор. Строгий выговор учитывается в планшете как два активных выговора. Беседа в планшет не вносится. Военнослужащий обязан отработать активный выговор в течение 48 часов с момента его выдачи в порядке, установленном командованием или руководителем подразделения. Если активный выговор не отработан в течение 48 часов, военнослужащему выдаётся дополнительный устный выговор. Если выговор не отработан в течение 96 часов с момента первоначальной выдачи, выдаётся ещё один устный выговор. Накопление трёх активных выговоров в планшете влечёт увольнение со службы. Решение об увольнении оформляется уполномоченным руководителем после проверки актуальности выговоров и обстоятельств их выдачи. Отработанный, снятый либо признанный необоснованным выговор не учитывается при подсчёте активных выговоров. Если медицинское освобождение объективно препятствует установленной форме отработки выговора, военнослужащему предоставляется возможность отработки способом, совместимым с медицинскими ограничениями. При отсутствии доступного совместимого способа течение сроков отработки, включая сроки 48 и 96 часов, приостанавливается на период подтверждённой невозможности отработки. После окончания указанного периода течение оставшегося срока возобновляется. Приостановление и возобновление срока фиксируются уполномоченным должностным лицом. За период приостановления дополнительные взыскания за просрочку не применяются.","r":"ДУ ст. 6.1"},{"d":"Дисциплинарный устав","t":"Статья 7. Порядок рассмотрения нарушения","x":"До применения взыскания уполномоченное лицо устанавливает обстоятельства нарушения, проверяет доступные доказательства и, когда это возможно, получает объяснение лица, в отношении которого ведётся проверка. Решение должно содержать существо нарушения, применённую норму и вид взыскания. Лицо вправе обжаловать решение командованию либо в иной предусмотренный проектом орган. Неустранимые сомнения в обстоятельствах проступка толкуются в пользу военнослужащего или сотрудника.","r":"ДУ ст. 7"},{"d":"Дисциплинарный устав","t":"Статья 8. Нарушение субординации","x":"Неисполнение законного приказа, неуважительное обращение к командиру или иному старшему по должности, а равно действия, препятствующие исполнению приказа, являются нарушением субординации. Оскорбление, угроза, насилие либо иное грубое воздействие в отношении командира или старшего по должности рассматриваются как грубое нарушение субординации. Возможные меры: устный выговор, строгий выговор или увольнение при угрозе, насилии либо грубой повторности.","r":"ДУ ст. 8"},{"d":"Дисциплинарный устав","t":"Статья 9. Самовольное оставление места службы","x":"Самовольное оставление части, подразделения, места несения службы или самовольное прекращение исполнения служебной задачи без уважительной причины является дисциплинарным проступком. Тяжесть проступка определяется с учётом продолжительности отсутствия, последствий и статуса военнослужащего. Обстоятельства, объективно исключавшие возможность прибыть или продолжить службу, подлежат учёту. Подтверждённая невозможность продолжения службы по состоянию здоровья, экстренное обращение за медицинской помощью или эвакуация подлежат обязательному учёту при рассмотрении обстоятельств отсутствия. Невозможность своевременно доложить о состоянии здоровья сама по себе не образует нарушение, если она была объективно обусловлена состоянием военнослужащего. При первой возможности военнослужащий либо медицинский работник уведомляет командование. Возможные меры: устный выговор, строгий выговор или увольнение при оставлении поста, существенных последствиях либо повторном нарушении.","r":"ДУ ст. 9"},{"d":"Дисциплинарный устав","t":"Статья 10. Уклонение от службы и обязательных мероприятий","x":"Неявка без уважительной причины на обязательное построение, занятие, медицинский осмотр, инструктаж, служебное мероприятие или иной обязательный формат службы является дисциплинарным проступком. Уклонением от службы также является намеренное прекращение уже принятого военнослужащим наряда, патруля либо иной служебной задачи без передачи её в установленном порядке. Действующее медицинское освобождение является уважительной причиной неисполнения тех обязанностей и неявки на те мероприятия, на которые распространяются установленные ограничения. Ответственность за неявку на медицинский осмотр применяется при условии, что осмотр назначен уполномоченным лицом, требование доведено до военнослужащего и у него имелась возможность явиться. Несение постовой службы до прибытия смены, получение экстренной помощи и иные подтверждённые обстоятельства, объективно препятствующие явке, учитываются при установлении вины. Возможные меры: беседа, устный выговор, строгий выговор; при грубой повторности или срыве служебной задачи - увольнение.","r":"ДУ ст. 10"},{"d":"Дисциплинарный устав","t":"Статья 11. Нарушение порядка несения службы","x":"Ненадлежащее несение караульной, патрульной, внутренней или иной служебной обязанности, если оно создало угрозу безопасности, порядку или имуществу, является дисциплинарным проступком. Самостоятельное заступление на пост или патруль допускается в рамках действующих уставов. Отсутствие индивидуального назначения либо журнала поста не освобождает лицо от ответственности за нарушение фактически принятой им службы. Возможные меры: беседа, устный выговор или строгий выговор; при создании угрозы безопасности, существенном вреде либо грубой повторности - увольнение.","r":"ДУ ст. 11"},{"d":"Дисциплинарный устав","t":"Статья 12. Нарушение порядка и общественной безопасности","x":"Действия или бездействие военнослужащего, нарушающие общественный порядок, безопасность военного объекта, установленный режим либо создающие угрозу гражданам, военнослужащим или имуществу, являются дисциплинарным проступком. Возможные меры: беседа, устный выговор или строгий выговор; при серьёзной угрозе безопасности, значимых последствиях либо грубой повторности - увольнение.","r":"ДУ ст. 12"},{"d":"Дисциплинарный устав","t":"Статья 12.1. Нарушение требований пожарной безопасности","x":"Нарушение требований пожарной безопасности, неосторожное обращение с огнём, создание пожароопасной ситуации, использование источников огня в запрещённой зоне либо игнорирование требований безопасности на складе, в казарме, гараже, технике или ином объекте Армии является дисциплинарным проступком. За нарушение может применяться беседа, устный выговор или строгий выговор. Если нарушение создало реальную угрозу жизни, повлекло ущерб имуществу либо совершено повторно, применяется строгий выговор или увольнение. Курение, использование электронных устройств для курения, кальянов и иных аналогичных средств в помещениях, на посту, на складе, вблизи техники, вооружения, горюче-смазочных материалов либо в иной запрещённой зоне является нарушением требований пожарной безопасности. Возможные меры: беседа, устный выговор или строгий выговор; при реальной угрозе жизни, ущербе имуществу либо повторном нарушении - строгий выговор или увольнение.","r":"ДУ ст. 12.1"},{"d":"Дисциплинарный устав","t":"Статья 13. Повреждение, утрата и незаконное использование имущества","x":"Умышленные либо небрежные действия, повлекшие утрату, порчу, повреждение или неправомерное использование государственного, ведомственного либо чужого имущества, являются дисциплинарным проступком. Нарушение, содержащее признаки преступления или административного правонарушения, передаётся для рассмотрения в порядке, установленном законодательством. Хищение, присвоение, незаконное удержание либо передача государственного, ведомственного или чужого имущества без законных оснований является грубым дисциплинарным проступком. За такое нарушение применяется строгий выговор или увольнение в зависимости от стоимости имущества, обстоятельств и последствий; при наличии признаков нарушения законодательства материалы передаются уполномоченному органу. Положения настоящей статьи распространяются на медицинские препараты, медицинское имущество и расходные материалы. Нарушение порядка учёта без установленных фактов утраты, присвоения, незаконной передачи или использования имущества не признаётся автоматически хищением либо утратой и оценивается по фактическим обстоятельствам. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от характера вины, стоимости имущества и наступивших последствий.","r":"ДУ ст. 13"},{"d":"Дисциплинарный устав","t":"Статья 14. Оружие, боеприпасы и специальные средства","x":"Нарушение правил хранения, учёта, переноски, передачи или применения оружия, боеприпасов и специальных средств является дисциплинарным проступком. Утеря, порча, оставление без присмотра либо небрежное хранение указанных предметов рассматриваются с учётом создаваемой опасности и наступивших последствий. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от опасности нарушения, последствий и повторности.","r":"ДУ ст. 14"},{"d":"Дисциплинарный устав","t":"Статья 15. Состояние опьянения и запрещённые вещества","x":"Появление на службе в состоянии алкогольного, наркотического или иного опьянения, употребление запрещённых веществ во время службы, а равно необоснованный отказ от освидетельствования в случаях, предусмотренных законодательством, являются дисциплинарными проступками. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 15"},{"d":"Дисциплинарный устав","t":"Статья 16. Бездействие командира и незаконное привлечение к ответственности","x":"Умышленное бездействие командира при наличии сведений о существенном нарушении, сокрытие такого нарушения или воспрепятствование его проверке является дисциплинарным проступком. Привлечение военнослужащего к ответственности без оснований, вне компетенции либо с нарушением установленного порядка также является дисциплинарным проступком. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 16"},{"d":"Дисциплинарный устав","t":"Статья 17. Военная форма и внешний вид","x":"Нарушение правил ношения военной формы, знаков различия, средств индивидуальной защиты и иных обязательных элементов внешнего вида является дисциплинарным проступком, если оно не обусловлено служебной необходимостью. Требования к причёске, растительности на лице и гигиене устанавливаются общим уставом и обязательны в пределах, прямо предусмотренных таким уставом. Возможные меры: беседа, устный выговор или строгий выговор при повторном либо демонстративном нарушении.","r":"ДУ ст. 17"},{"d":"Дисциплинарный устав","t":"Статья 18. Честь ведомства и дискредитация","x":"Публичные действия, высказывания или материалы, содержащие оскорбление ведомства, его символики либо необоснованно подрывающие авторитет Вооружённых Сил или ФСВНГ, являются дисциплинарным проступком. Критика, обращение с жалобой или сообщение о нарушении не образуют проступка, если они сделаны добросовестно и в законной форме. Возможные меры: устный выговор, строгий выговор или увольнение при грубом, публичном либо повторном нарушении.","r":"ДУ ст. 18"},{"d":"Дисциплинарный устав","t":"Статья 19. Служебная информация и документы","x":"Разглашение охраняемой служебной информации, несанкционированный доступ к ней, подделка, уничтожение или неправомерное использование служебных документов являются дисциплинарными проступками. Предоставление заведомо ложных сведений в рапорте, объяснении, отчёте или ином служебном документе рассматривается как самостоятельный проступок. К служебным документам относятся приказы и приказания, директивы, рапорты и доклады, акты и протоколы, справки и удостоверения, медицинские карточки, заключения, направления и документы учёта медицинских препаратов и имущества. Подделка таких документов, оформление фиктивного осмотра или освобождения, внесение заведомо ложных сведений, несанкционированное изменение записей либо разглашение охраняемых медицинских сведений рассматриваются по настоящей статье. Добросовестная техническая ошибка, исправленная в установленном порядке, сама по себе не признаётся подделкой или предоставлением заведомо ложных сведений. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от характера информации, последствий и повторности.","r":"ДУ ст. 19"},{"d":"Дисциплинарный устав","t":"Статья 20. Злоупотребление полномочиями и конфликт интересов","x":"Использование служебных полномочий, имущества, доступа, транспорта либо специального статуса в личных интересах, а также принятие решения при неурегулированном конфликте интересов являются дисциплинарными проступками. Служебные полномочия не могут использоваться для личной выгоды, давления на граждан или военнослужащих либо обхода установленной процедуры. Использование медицинского осмотра, заключения, освобождения или направления на обследование для личной выгоды, давления, мести либо вмешательства в кадровые решения вне предоставленных полномочий является злоупотреблением. Медицинское освобождение не допускается использовать в качестве дисциплинарного наказания. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 20"},{"d":"Дисциплинарный устав","t":"Статья 21. Поведение в строю и на территории части","x":"Военнослужащий обязан соблюдать порядок на построениях, плацу, в казармах и на территории части, не мешать проведению служебных мероприятий и не создавать опасность другим лицам. Самовольное передвижение бегом по плацу во время проведения построения при наличии сформированного строя запрещается. Исключение составляют случаи исполнения команды или распоряжения командования. Возможные меры: беседа, устный выговор или строгий выговор при повторном нарушении, срыве мероприятия либо создании опасности.","r":"ДУ ст. 21"},{"d":"Дисциплинарный устав","t":"Статья 22. Символика, ритуалы и азартные игры","x":"Надругательство над государственными или ведомственными символами, срыв установленного воинского ритуала, а также организация или участие в азартных играх в служебное время либо на служебной территории являются дисциплинарными проступками. Возможные меры: устный выговор, строгий выговор или увольнение при грубом, публичном либо повторном нарушении.","r":"ДУ ст. 22"},{"d":"Дисциплинарный устав","t":"Статья 23. Самоуправство и неуставные взаимоотношения","x":"Принуждение военнослужащего к действиям, не предусмотренным законодательством, уставом или законным приказом, самовольное применение взысканий, а равно унижение, травля или неуставное воздействие на подчинённого являются дисциплинарными проступками. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 23"},{"d":"Дисциплинарный устав","t":"Статья 24. Оказание помощи","x":"Неоказание посильной помощи раненому, пострадавшему, военнослужащему, гражданину либо сотруднику, находящемуся в опасном состоянии, когда помощь могла быть оказана без неоправданного риска, является дисциплинарным проступком. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от опасности ситуации и последствий неоказания помощи.","r":"ДУ ст. 24"},{"d":"Дисциплинарный устав","t":"Статья 25. Заведомо ложное сообщение и клевета","x":"Заведомо ложное сообщение о нарушении, преступлении или происшествии, а равно распространение заведомо недостоверных сведений, порочащих честь и достоинство другого лица, является дисциплинарным проступком. Возможные меры: устный выговор, строгий выговор или увольнение при тяжких последствиях, грубой клевете либо повторном нарушении.","r":"ДУ ст. 25"},{"d":"Дисциплинарный устав","t":"Статья 26. Воспрепятствование законной деятельности","x":"Неповиновение законным требованиям уполномоченного сотрудника, создание препятствий проверке, служебному мероприятию либо законной деятельности государственного органа является дисциплинарным проступком. Возможные меры: устный выговор, строгий выговор или увольнение при умышленном срыве законной деятельности, угрозе либо грубой повторности.","r":"ДУ ст. 26"},{"d":"Дисциплинарный устав","t":"Статья 27. Халатность","x":"Неисполнение либо ненадлежащее исполнение обязанностей вследствие недобросовестного отношения к службе, если это повлекло или могло повлечь вред безопасности, порядку, имуществу или интересам службы, является дисциплинарным проступком. При оценке исполнения медицинских обязанностей учитываются подготовка работника, предоставленные полномочия, доступность необходимых средств и фактическая возможность оказать помощь. Неблагоприятный результат оказания помощи сам по себе не доказывает халатность. Необходимо установить конкретное нарушение обязанности, вину и предусмотренные настоящей статьёй обстоятельства. Неисполнение командиром доведённых до него действующих медицинских ограничений при наличии возможности обеспечить их соблюдение оценивается по настоящей статье либо иной применимой специальной норме с учётом характера вины и последствий. Возможные меры: беседа, устный выговор, строгий выговор или увольнение в зависимости от возможного либо наступившего вреда.","r":"ДУ ст. 27"},{"d":"Дисциплинарный устав","t":"Статья 28. Связи с преступной деятельностью","x":"Сокрытие достоверно известных сведений о подготовке либо совершении преступления, а также использование служебного положения в интересах преступной деятельности является дисциплинарным проступком и подлежит передаче для рассмотрения по законодательству. Возможные меры: строгий выговор или увольнение. Материалы подлежат передаче для рассмотрения по законодательству.","r":"ДУ ст. 28"},{"d":"Дисциплинарный устав","t":"Статья 29. Режим объекта, связь и транспорт","x":"Нарушение пропускного и внутриобъектового режима, правил служебной связи или использования служебного транспорта является дисциплинарным проступком. Ведение отдельного журнала поста или назначение военнослужащего на пост не являются обязательными условиями для признания нарушения. Значимые инциденты фиксируются служебным сообщением, рапортом либо иным установленным способом. Использование личного транспорта на территории воинской части допускается только по маршрутам и через пункты пропуска, прямо определённые действующим караульным уставом или распоряжением командования. Возможные меры: беседа, устный выговор или строгий выговор; при создании угрозы безопасности, существенных последствиях либо грубой повторности - увольнение.","r":"ДУ ст. 29"},{"d":"Дисциплинарный устав","t":"Статья 30. Иные нарушения","x":"Нарушение обязанностей, прямо установленных законодательством, настоящим Уставом, иными уставами или законным приказом, может являться дисциплинарным проступком при наличии вины и доказанных обстоятельств. Общая формулировка настоящей статьи не применяется для обхода специальных норм Устава или назначения взыскания за поведение, которое не было заранее запрещено либо не нарушило законную обязанность. Возможные меры: беседа, устный выговор или строгий выговор в пределах нарушенной конкретной нормы. Увольнение не может назначаться только на основании настоящей статьи.","r":"ДУ ст. 30"},{"d":"Дисциплинарный устав","t":"Статья 31. Основания для поощрения","x":"Поощрение применяется за добросовестную службу, инициативу, образцовое исполнение обязанностей, успешное выполнение сложной задачи, помощь подразделению, дисциплинированность и иные заслуги перед ведомством.","r":"ДУ ст. 31"},{"d":"Дисциплинарный устав","t":"Статья 32. Виды поощрений","x":"В пределах компетенции могут применяться следующие меры поощрения: - снятие ранее наложенного дисциплинарного взыскания; - объявление благодарности; - награждение ценным подарком либо денежной премией в порядке, установленном проектом; - досрочное присвоение очередного звания или представление к повышению; - занесение в книгу почёта либо иную форму публичного признания заслуг.","r":"ДУ ст. 32"},{"d":"Дисциплинарный устав","t":"Статья 33. Порядок применения поощрений","x":"Поощрение объявляется уполномоченным должностным лицом и должно быть обосновано конкретными заслугами военнослужащего или сотрудника. Поощрение не освобождает от ответственности за совершённые нарушения.","r":"ДУ ст. 33"},{"d":"Дисциплинарный устав","t":"Статья 34. Применение Устава","x":"Настоящий Устав применяется совместно с общим уставом Вооружённых Сил, уставом караульно-постовой службы и действующим законодательством проекта. Положения Устава подлежат периодическому пересмотру командованием при изменении законодательства, структуры ведомств или игровых механик. Изменения не могут ухудшать положение лица задним числом.","r":"ДУ ст. 34"},{"d":"Дисциплинарный устав","t":"Статья 35. Толкование","x":"Официальное толкование положений настоящего Устава осуществляется уполномоченным руководством проекта в соответствии с законодательством. При наличии пробела применяется наиболее близкая по смыслу норма с соблюдением принципов справедливости, соразмерности и презумпции добросовестности.","r":"ДУ ст. 35"},{"d":"Устав караульно-постовой службы","t":"Статья 1","x":"Настоящий Устав определяет предназначение, порядок организации и несения караульной службы, права и обязанности военнослужащих, несущих караульную службу, а также для регламентирует порядок несения постовой службы военнослужащих ВС РФ, а так же ФСВНГ.","r":"УКПС ст. 1"},{"d":"Устав караульно-постовой службы","t":"Статья 2","x":"Настоящим Уставом руководствуются все военнослужащие органов военного управления, воинских частей, органов военной полиции,федеральной службы войск национальной гвардии и лица гражданского персонала Вооруженных Сил Российской Федерации, замещающие воинские должности.","r":"УКПС ст. 2"},{"d":"Устав караульно-постовой службы","t":"Статья 3","x":"Караульная служба предназначена для надежной охраны и обороны боевых знамен, хранилищ (складов) с вооружением, военной техникой, другим военным имуществом, объектов Вооруженных Сил Российской Федерации и иных военных и государственных объектов, а также для охраны военнослужащих, содержащихся на гауптвахте и в дисциплинарной части.","r":"УКПС ст. 3"},{"d":"Устав караульно-постовой службы","t":"Статья 4","x":"Руководство караульной службой внутренних караулов воинский частей осуществляют командиры этих частей и их прямые начальники.","r":"УКПС ст. 4"},{"d":"Устав караульно-постовой службы","t":"Статья 5","x":"Приказы и распоряжения Министра обороны командующих территориальными воинскими формированиями по организации и несению караульной службы обязательным для выполнения подведомственными воинскими формированиями, их военнослужащими и иными должностными лицами, входящими в состав конкретного субъекта.","r":"УКПС ст. 5"},{"d":"Устав караульно-постовой службы","t":"Статья 6","x":"Командующие воинскими формированиями обязаны периодически проверять качество несения караульной службы на подведомственных субъектах.","r":"УКПС ст. 6"},{"d":"Устав караульно-постовой службы","t":"Статья 7","x":"При расположении войск в полевых условиях мероприятия по поддержанию воинской дисциплины, охране субъектов воинских частей и военных объектов проводятся в соответствии с Уставами воинских формирований Вооруженных Сил Российской Федерации и настоящим Уставом.","r":"УКПС ст. 7"},{"d":"Устав караульно-постовой службы","t":"Статья 8","x":"Непосредственное выполнение задач караульной службы осуществляется подразделениями воинских частей, отделом собственной безопасности а также военной комендатурой в пределах компетенции, определенной настоящим Уставом и Уставами конкретных воинских формирований.","r":"УКПС ст. 8"},{"d":"Устав караульно-постовой службы","t":"Статья 9","x":"Каждый военнослужащий обязан оказывать требуемую помощь лицам, несущим караульную службу.","r":"УКПС ст. 9"},{"d":"Устав караульно-постовой службы","t":"Статья 10","x":"Каждый военнослужащий обязан знать в лицо своего командира или зам командира","r":"УКПС ст. 10"},{"d":"Устав караульно-постовой службы","t":"Статья 11","x":"Военнослужащий, заметив нарушение правил несения службы кем-либо из состава наряда, караула, обязан немедленно сообщить об этом дежурному по части, в орган военной полиции или отдел собственной безопасности и доложить непосредственному командиру (начальнику).","r":"УКПС ст. 11"},{"d":"Устав караульно-постовой службы","t":"Статья 12","x":"Начальником караульной службы является командир части либо назначенное приказом должностное лицо.","r":"УКПС ст. 12"},{"d":"Устав караульно-постовой службы","t":"Статья 13","x":"К постоянным караулам относятся караулы, перечень которых определяется настоящим Уставом и караульная служба на которых осуществляется непрерывно без необходимости оформления сопроводительных документов или письменных и(или) устных распоряжений на организацию и осуществление караулов.","r":"УКПС ст. 13"},{"d":"Устав караульно-постовой службы","t":"Статья 14","x":"Временные караулы создаются приказами командиров воинских частей (формирований) либо приказом (указом) Министра обороны Российской Федерации, Премьер-министра и иными должностными лицами, которым предоставлено такое право в соответствии с действующим законодательством Российской Федерации.","r":"УКПС ст. 14"},{"d":"Устав караульно-постовой службы","t":"Статья 15","x":"Перечень постоянных караулов на территории Московской области: воинская часть ; территориальные военные объекты материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения; военный комиссариат Московской области, пункты отборы; государственные объекты материального снабжения.","r":"УКПС ст. 15"},{"d":"Устав караульно-постовой службы","t":"Статья 16","x":"Порядок несения караульной службы, перечень постов в караулах и порядок посещения указанных в статье 13 территорий, определяется настоящим Уставом.","r":"УКПС ст. 16"},{"d":"Устав караульно-постовой службы","t":"Статья 17","x":"Порядок несения караульной службы и перечень постов в караулах на объектах материального снабжения и объекта стратегического значения защищен Федеральным законом \"О государственной тайне\" и устанавливается исключительно приказами командиров (начальников) воинских формирований в соответствии с подведомственностью.","r":"УКПС ст. 17"},{"d":"Устав караульно-постовой службы","t":"Статья 18","x":"Каждый из перечисленных в статье 13 настоящего Устава объект охраняется Вооруженными Силами Российской Федерации. 18.1 Военные склады материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения, территории воинских частей являются закрытыми для свободного посещения и нахождения. Порядок прохода и пребывания на указанных территориях определяется Федеральным законом \"О государственной собственности, закрытых и охраняемых территориях\" и Федеральным законом \"О Вооруженных Силах Российской Федерации\" . 18.2 Нахождение на иных территориях, не перечисленных в части 1 статьи 16 настоящего Устава, не ограничивается при соблюдении установленных правил поведения, за исключением обстоятельств, определяемых действующим законодательством. Раздел 3. Постовая служба в караулах","r":"УКПС ст. 18"},{"d":"Устав караульно-постовой службы","t":"Статья 19","x":"Заступить на постовую службу в караулах может любой военнослужащих со звания Рядовой","r":"УКПС ст. 19"},{"d":"Устав караульно-постовой службы","t":"Статья 20","x":"Перечень постов в каждом из постоянных караулов определяется настоящим Уставом, может дополняться и корректироваться в связи с определенными обстоятельствами приказами командиров воинских частей (формирований), Министра обороны Российской Федерации.","r":"УКПС ст. 20"},{"d":"Устав караульно-постовой службы","t":"Статья 21","x":"Перечень постов во временно организуемых караулах определяется соответствующим приказом (указом) командиров (начальников), Министра обороны Российской Федерации, Премьер-министра, иных должностных лиц в пределах компетенции.","r":"УКПС ст. 21"},{"d":"Устав караульно-постовой службы","t":"Статья 22","x":"Перечень постов в карауле на территории воинской части: контрольно-пропускной пункт №1 (главный КПП); контрольно-пропускной пункт №2 (запасной КПП); вышки №1 - №8 по периметру воинской части; главный склад; военный полигон.","r":"УКПС ст. 22"},{"d":"Устав караульно-постовой службы","t":"Статья 22.1","x":"На территории военного полигона “Алабино” устанавливаются три постоянных поста: - контрольно-пропускной пункт №1; - контрольно-пропускной пункт №2; - наблюдательная вышка. Оба КПП являются основными пунктами прохода, въезда и выезда на и с территории полигона. Наблюдательная вышка предназначена для визуального контроля территории, выявления нарушений режима, незаконного проникновения, происшествий и своевременного доклада по средствам связи. Дежурство на постах несут военнослужащие мотострелкового корпуса и роты вневедомственной охраны","r":"УКПС ст. 22.1"},{"d":"Устав караульно-постовой службы","t":"Статья 22.2","x":"На территории военного полигона “Алабино” допускается пешее и автомобильное патрулирование. Патрулирование может осуществляться военнослужащими, самостоятельно заступившими на патрульную службу, либо военнослужащими, действующими по распоряжению командования. Отдельное назначение на патруль не является обязательным условием его несения. Патруль обязан контролировать режим территории, выявлять незаконное проникновение, обеспечивать безопасность вблизи зон проведения учений и тренировок, не препятствовать учебным мероприятиям и докладывать о выявленных нарушениях по рации.","r":"УКПС ст. 22.2"},{"d":"Устав караульно-постовой службы","t":"Статья 23","x":"Перечень постов в карауле на территории военного комиссариата, пунктов отбора: главный вход; призывной кабинет; дежурный пост.","r":"УКПС ст. 23"},{"d":"Устав караульно-постовой службы","t":"Статья 24","x":"Численность военнослужащих одновременно несущих караульно-постовую службу на территории воинской части устанавливается внутренними актами и должностными регламентами","r":"УКПС ст. 24"},{"d":"Устав караульно-постовой службы","t":"Статья 25","x":"Старший наряда назначается приказом. Старшинство по званию применяется только при отсутствии назначенного старшего наряда.","r":"УКПС ст. 25"},{"d":"Устав караульно-постовой службы","t":"Статья 26","x":"При приеме и сдаче поста проверяются оружие, средства связи, состояние охраняемого объекта, наличие происшествий и замечаний. Смена фиксируется докладом в рацию.","r":"УКПС ст. 26"},{"d":"Устав караульно-постовой службы","t":"Статья 26.1. Ухудшение состояния здоровья постового","x":"При ухудшении состояния здоровья постовой незамедлительно докладывает дежурному либо старшему наряда и запрашивает медицинскую помощь. Для прохождения планового медицинского осмотра постовой сдаёт пост сменяющему военнослужащему в порядке статьи 26 настоящего Устава. Самостоятельный уход с поста для планового осмотра до сдачи поста не допускается. Если состояние здоровья исключает безопасное продолжение службы либо требуется экстренная помощь, медицинская помощь оказывается безотлагательно. Дежурный либо старший наряда организует замену и обеспечивает непрерывность охраны объекта. При невозможности постового самостоятельно доложить о своём состоянии доклад осуществляет обнаруживший его военнослужащий либо медицинский работник. Военнослужащий с действующими медицинскими ограничениями не допускается к постовой службе, если её условия несовместимы с указанными ограничениями. Доклад и передача поста осуществляются по служебной связи. Ведение отдельного журнала поста для этого не требуется.","r":"УКПС ст. 26.1"},{"d":"Устав караульно-постовой службы","t":"Статья 27","x":"Бодикамера обязательна для сотрудников ВП, ОСБ, военнослужащих на КПП, патрулей и лиц, проводящих задержание. При неисправности камеры военнослужащий докладывает старшему.","r":"УКПС ст. 27"},{"d":"Устав караульно-постовой службы","t":"Статья 28","x":"При заступлении на пост, каждый военнослужащий обязан предварительно провести проверку табельного оружия и средств радиосвязи на предмет их исправности. При обнаружении неисправности в работе, принять меры по устранению поломки либо заменить на исправные. Постовой или патрульный не вправе использовать полученное для службы оружие в личных целях, передавать его другим лицам либо покидать с ним территорию части без служебной необходимости.","r":"УКПС ст. 28"},{"d":"Устав караульно-постовой службы","t":"Статья 29","x":"При несении постовой службы запрещается: терять концентрацию, отвлекаться на телефон и иные электронные средства, на разговоры; оставлять вооружение без контроля, снимать его с плеча без необходимости привести его в боевую готовность; нарушать действующее законодательство, особенно в области этики; игнорировать запросы о состоянии поста в рацию; своевременно не докладывать о состоянии поста; нарушать требования настоящего Устава в области организации пропуска на территорию и с территории объекта; бездействовать при совершении преступлений и(или) правонарушений на подведомственных территориях; бездействовать при просьбе оказания помощи гражданам и сотрудникам в пределах компетенции. Военнослужащим во время несения постовой службы на любом посту запрещается танцевать и совершать иные действия, не связанные с исполнением служебных обязанностей. Разрешено совершать действия, непосредственно необходимые для выполнения уставных предписаний, применения разрешённого снаряжения или оказания медицинской помощи.","r":"УКПС ст. 29"},{"d":"Устав караульно-постовой службы","t":"Статья 30","x":"Обязанности военнослужащих, несущих постовую службу на КПП №1: постовой проверяет документы водителя, номер автомобиля, цель въезда и наличие записи в журнале транспортных средств. При отказе от предусмотренной проверки въезд не допускается. Постовой также проверяет документы прибывающих лиц, докладывает о нарушениях, пресекает незаконное проникновение в пределах полномочий и своевременно докладывает о состоянии поста. Полковники и выше проходят без оформления увольнительной, но предъявляют служебное удостоверение. При покидании воинской части на личном транспорте или без установленной формы одежды, независимо от занимаемой должности, военнослужащий обязан предъявить удостоверение постовому и не препятствовать осмотру багажника транспортного средства (( постовой вправе через отыгровку типа “/do Есть ли в машине @dynamicID запрещенные или нелегальные средства?”, игнорирование вопроса или заведомо ложный ответ наказывается по 5.9 ОПП )). Постовой вправе проводить досмотр военнослужащих, гражданских лиц, ручной клади и транспортных средств при въезде или выезде с территории воинской части в целях соблюдения пропускного режима, выявления запрещенных предметов и проверки законности ношения оружия, боеприпасов и специальных средств. Военнослужащий, покидающий часть в гражданской форме, обязан по требованию постового подтвердить сдачу оружия, боеприпасов и специальных средств в порядке, установленном внутренним уставом (статья 3.4.2 ВУ). При выявлении оружия, боеприпасов или специальных средств у лица, которое обязано было их сдать, постовой не допускает дальнейший выход с территории части и направляет лицо на склад вооружения для сдачи снаряжения.","r":"УКПС ст. 30"},{"d":"Устав караульно-постовой службы","t":"Статья 31","x":"Военнослужащие со звания генерал-лейтенант включительно освобождаются от проверок при пересечении любого из КПП, постовые обязаны знать их в лицо.","r":"УКПС ст. 31"},{"d":"Устав караульно-постовой службы","t":"Статья 32","x":"КПП №2 является резервно-служебным. Он используется для колонн снабжения, призывных колонн, служебного транспорта, патрулей и правительственных кортежей только при закрытии КПП №1 либо по отдельному приказу командования.","r":"УКПС ст. 32"},{"d":"Устав караульно-постовой службы","t":"Статья 33","x":"Обязанности военнослужащих на КПП №2 аналогичны обязанностям на КПП №1 и выполняются только в период законного использования КПП №2.","r":"УКПС ст. 33"},{"d":"Устав караульно-постовой службы","t":"Статья 34","x":"На территорию воинской части запрещается въезд на личных транспортных средствах, не зарегистрированных в установленном порядке в журнале транспортных средств. Регистрацию автомобиля санкционируют командиры ВП и ОСБ в пределах полномочий.","r":"УКПС ст. 34"},{"d":"Устав караульно-постовой службы","t":"Статья 34.2","x":"Въезд личного транспорта военнослужащих и гражданских лиц допускается исключительно через КПП №1. КПП №2 не используется для въезда личного транспорта.","r":"УКПС ст. 34.2"},{"d":"Устав караульно-постовой службы","t":"Статья 34.3","x":"Личный транспорт допускается при наличии записи в журнале транспортных средств и подтвержденной цели въезда.","r":"УКПС ст. 34.3"},{"d":"Устав караульно-постовой службы","t":"Статья 34.4","x":"После въезда личный транспорт следует по утвержденному маршруту на выделенную парковочную зону. Сквозной проезд по территории части, остановка у штаба, складов, казарм, автопарка, постов и иных режимных объектов запрещены.","r":"УКПС ст. 34.4"},{"d":"Устав караульно-постовой службы","t":"Статья 34.5","x":"Выезд личного транспорта производится через КПП №1. Допуск автомобиля может быть приостановлен или отменен при отсутствии транспортного средства в журнале.","r":"УКПС ст. 34.5"},{"d":"Устав караульно-постовой службы","t":"Статья 35","x":"Разовые пропуска на территорию части уполномочены оформлять командиры военной полиции и руководство вооруженных сил.","r":"УКПС ст. 35"},{"d":"Устав караульно-постовой службы","t":"Статья 36","x":"Военнослужащим несущим постовую службу на контрольно-пропускном пункте №1 и контрольно-пропускном пункте № 2 запрещается : 1. Спать, сидеть и прислоняться к чему-либо. 2. Читать, писать, петь. 3. Есть, пить и курить. 4. Принимать от кого-либо или передавать кому-либо предметы, не связанные с исполнением служебных обязанностей. Запрет не распространяется на установленную передачу служебного имущества, получение разрешённых средств первой помощи и действия, необходимые для оказания медицинской помощи. 5. Справлять естественные надобности на посту. 6. Досылать патрон в патронник без необходимости, как и доставать оружие без необходимости. 7. Использовать средства личной связи. 8. Танцевать или совершать иные действия, не связанные с несением постовой службы.","r":"УКПС ст. 36"},{"d":"Устав караульно-постовой службы","t":"Статья 37","x":"Режимным объектом является территория внутри периметра части, доступ к которой осуществляется через КПП №1 и КПП №2. Территория с внешней стороны КПП режимным объектом не является. За пределами режимного объекта военнослужащие действуют в пределах закона и при необходимости вызывают компетентные органы.","r":"УКПС ст. 37"},{"d":"Лекция «Постовая служба»","t":"Общее","x":"# Лекция: Постовая служба Автор: Инст.ОМОН | В.Спасская | 27564 (Майор). Даты: 29.08 – 04.09.2026. Схема постов (Google Docs): https://docs.google.com/document/d/19sdovoOBFjQMLX88zS3jm_zHjUxrcbWXFVT9O7cO-qk/edit?tab=t.0 > Постовая служба — одна из ключевых задач военнослужащего: защита территории от несанкционированного проникновения и поддержание порядка на посту.","r":""},{"d":"Лекция «Постовая служба»","t":"1. Шаблоны докладов в `/f` — главное для отчёта","x":"Формат единый, меняется только средняя часть: /f Докладывает [Звание] Росгвардии [Имя Фамилия] - время [ЧЧ:ММ] - [КПП№N Алабино / Вышка \"Название\"] - заступил на пост - состояние стабильное - доклад окончил. /f Докладывает [Звание] Росгвардии [Имя Фамилия] - время [ЧЧ:ММ] - [КПП№N Алабино / Вышка \"Название\"] - состояние стабильное - доклад окончил. /f Докладывает [Звание] Росгвардии [Имя Фамилия] - время [ЧЧ:ММ] - [КПП№N Алабино / Вышка \"Название\"] - пост сдал - состояние стабильное - доклад окончил.","r":""},{"d":"Лекция «Постовая служба»","t":"Эталонный пример (из лекции)","x":"/f Докладывает Полковник Росгвардии Василиса Спасская - время 16:00 - КПП№1 Алабино - заступил на пост - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 16:15 - КПП№1 Алабино - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 16:30 - КПП№1 Алабино - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 16:45 - КПП№1 Алабино - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 17:00 - КПП№1 Алабино - пост сдал - состояние стабильное - доклад окончил. ⚠️ Чат — /f (IC, рация), не /fb. Доклад каждые 15 минут.","r":""},{"d":"Лекция «Постовая служба»","t":"2. Расстановка постов (полигон Алабино)","x":"Пост — Расстановка — Кол-во КПП №1 Алабино — Два военнослужащих слева и справа от ворот, один за воротами — 3 КПП №2 Алабино — Два военнослужащих слева и справа от шлагбаума, один за шлагбаумом — 3 Наблюдательная вышка Алабино — Два военнослужащих — 2 Вышка «Оружейки» — Один военнослужащий — 1 Вышка «Огневой рубеж» — Один военнослужащий — 1 Вышка «Лагерь» — Один военнослужащий — 1 При заступлении в рации указывается конкретный пост (КПП или вышка).","r":""},{"d":"Лекция «Постовая служба»","t":"3. Основные задачи караульного","x":"1. Охрана КПП — не допустить проникновение лиц без соответствующих разрешений. 2. Регулярные доклады — о ситуации на посту каждые 15 минут. 3. Доклад при заступлении — в рацию /f, с указанием КПП/вышки. 4. Экипировка — заступать только в полной: бронежилет, оружие, патроны, сухпайки. 5. Знание командного состава — знать в лицо высокопоставленных чинов армии. 6. Проверка документов — у всех прибывающих: паспорт, служебное удостоверение, жетон, бейджик. 7. Вежливое общение — тактично, независимо от ситуации. 8. Взаимодействие с гос. структурами (ФСБ, ГИБДД, Больница, Правительство): - узнать цель прибытия; - запросить служебные удостоверения; - сообщить по рации о прибытии и ожидать указаний.","r":""},{"d":"Лекция «Постовая служба»","t":"4. Действия при проникновении","x":"1. Немедленно сообщить по рации — это позволяет оперативно организовать оборону. 2. Усилить бдительность — быть готовым к возможной атаке на пост. 3. При отсутствии прямой угрозы — задержать, выяснить обстоятельства, вывести за территорию.","r":""},{"d":"Лекция «Постовая служба»","t":"Категорически запрещено при проникновении","x":"- Покидать пост для нейтрализации нарушителей. - Игнорировать проникновение. - Паниковать и нарушать порядок на посту. - Самостоятельно вызывать поддержку других силовых структур (ФСБ, МВД). - Самостоятельно транспортировать задержанных в правоохранительные органы — это задача Военной Полиции.","r":""},{"d":"Лекция «Постовая служба»","t":"5. Караульному запрещено","x":"1. Отдавать, продавать табельное оружие, боеприпасы, форму и спец. принадлежности. 2. Покидать пост без причины или разрешения, а также не доложив об этом по рации. Пропускать через КПП посторонних лиц без разрешения старшего состава. *Исключение:* лица с доступом к ЗОТ — после проверки документов. 3. Спать на посту. 4. Вступать в контакт с гражданскими на КПП. *Исключение:* проверка документов, удостоверяющих личность, и цели визита. 5. Заступать в караул без полного боекомплекта и обмундирования. 6. Вести себя неподобающим образом: хамить гражданским и военнослужащим, сидеть или лежать на посту, включать музыку, танцевать, выполнять физ. упражнения. 7. Пользоваться мобильными средствами связи. 8. Открывать огонь по гражданским без видимой причины; доставать оружие без угрозы для жизни.","r":""},{"d":"Лекция по субординации","t":"Общее","x":"# Лекция: Субординация Автор: Инст.ОМОН | В.Спасская | 27564 (Майор). Дата: 29.08.2026.","r":""},{"d":"Лекция по субординации","t":"Понятие","x":"Субординация — строго установленная система подчинения по званию и должности, а также правила общения и поведения между военнослужащими. В Армии субординация: - обеспечивает чёткое выполнение приказов; - исключает хаос и самоуправство; - поддерживает уважение к званиям и командованию; - повышает эффективность подразделения.","r":""},{"d":"Лекция по субординации","t":"Иерархия","x":"Каждый военнослужащий обязан: - знать своё звание; - знать, кому он подчиняется. > Принцип: приказ старшего по званию или должности обязателен к выполнению, если он не нарушает устав и правила сервера.","r":""},{"d":"Лекция по субординации","t":"Речевые формулы — выучить дословно","x":"Ситуация — Ответ Согласие — «Так точно» Несогласие — «Никак нет» Получен приказ — «Есть» Хотите обратиться — «[Звание] [Фамилия], разрешите обратиться» Не знаете ответа — «Не могу знать» Обращение к старшим по званию — с использованием звания, в уважительной форме. С уважением обращаться нужно ко всем военнослужащим, независимо от их должности.","r":""},{"d":"Лекция по субординации","t":"Выполнение приказов","x":"Приказ — официальное распоряжение руководителя / командира / старшего по званию, обязательное для исполнения подчинёнными. Приказ: - выполняется быстро, точно, без личной инициативы; - не обсуждается публично; - может быть уточнён, если неясен.","r":""},{"d":"Лекция по субординации","t":"Запрещено","x":"- игнорировать приказ; - спорить с командиром; - самовольно менять задачу (проявлять инициативу); - выполнять приказы не от своего командира без разрешения.","r":""},{"d":"Лекция по субординации","t":"Дисциплинарная ответственность","x":"За нарушения правил внутреннего распорядка, внутреннего устава, НПА, а также уголовного, этического и трудового кодексов применяются взыскания: 1. устное предупреждение; 2. выговор (устный или строгий); 3. переаттестация; 4. понижение в звании; 5. увольнение из Армии (в тяжёлых случаях или при многочисленных нарушениях).","r":""},{"d":"Лекция по субординации","t":"Примеры нарушений","x":"Нарушение — Статья — Взыскание Вступать в неуставные отношения, спор или конфликт со старшим по званию — Ст. 23 ДУ — Предупреждение или выговор Игнорировать приказы старшего состава — ВУ ст. 1.3 (Беспрекословное выполнение приказов), ст. 5.4 (Сущность воинской дисциплины) — —","r":""},{"d":"Лекция «Строевая подготовка»","t":"Термины","x":"Термин — Определение Строй — Установленное Уставом размещение военнослужащих, подразделений и воинских частей для их совместных действий в пешем порядке и на машинах Шеренга — Строй, в котором военнослужащие размещены один возле другого на одной линии на установленных интервалах Колонна — Строй, в котором военнослужащие расположены в затылок друг другу, а подразделения (машины) — одно за другим на дистанциях, установленных Уставом или командиром","r":""},{"d":"Лекция «Строевая подготовка»","t":"Военнослужащим запрещено","x":"- Прогуливать либо опаздывать на построение без веской причины. - Самовольно покидать строй, а также вставать в уже сформированный строй без разрешения. → При опоздании: «[Звание] [Фамилия], разрешите встать в строй». - Выталкивать других военнослужащих из строя. - Совершать любые движения без команды (переодевать бронежилет, доставать оружие, доставать телефон и т.п.). - Разговаривать и издавать звуки без разрешения старших в строю. - Есть, пить, курить и совершать прочие повседневные действия вне построений. - Спать во время построения.","r":""},{"d":"Лекция «Строевая подготовка»","t":"Вечернее построение","x":"- Проводится в дни, указанные генералитетом в новостях армии. О построении сообщается в общую рацию. - Каждое подразделение докладывает о проделанной за день работе. - До личного состава доводится информация. - Нарушать дисциплину в строю запрещено (телефон, разговоры, сон, самовольный выход, непристойные движения). - Перед тем как встать в строй — снять бронежилет и убрать оружие из-за спины.","r":""},{"d":"Лекция «Строевая подготовка»","t":"Доклад старшего в подразделении начальнику","x":"[Начальник] Ответственный офицер, рота ведомственной охраны. [Старший] Я! [Начальник] Выйдите из строя, подойдите ко мне! [Старший] Есть! *Старший выходит из строя, по кратчайшей траектории подходит к начальнику, с последним шагом выполняет воинское приветствие. Начальник выполняет воинское приветствие.* [Старший] Товарищ [Звание], [Ваше звание/должность] по вашему приказанию прибыл! [Начальник] [Звание] [Фамилия Имя], доложить о проделанной работе за день! [Старший] Есть! Рота ведомственной охраны в составе [Кол-во] человек, для проведения вечерней поверки построена, лиц незаконно отсутствующих не выявлено. За [Число] [Месяц] Рота Ведомственной Охраны работала в штатном режиме, [что было проделано за день от вашего подразделения]. Жалоб и заявлений среди военнослужащих не выявлено. [Ваша должность/ранг] роты ведомственной охраны, [Фамилия Имя]. [Начальник] Вольно, стать в строй! *Начальник опускает руку.* [Старший] Есть! *Старший поворачивается к своему подразделению.* [Старший] Вольно! *С первым шагом опускает руку и возвращается на место в строю.*","r":""},{"d":"Принятие присяги","t":"Общее","x":"# Принятие присяги Когда: ежедневно 12:00 и 20:00 на плацу, а также в любое время по договорённости. О начале построения на присягу старший офицер докладывает в новости. Требование для повышения ранг 2 → 3. По ст. 1.11 Устава ВС присяга обязательна для каждого прибывшего в часть; отказ или грубое нарушение — основание для увольнения. > Присяга для ФСВНГ проводится отдельно от ВС РФ — будьте внимательны.","r":""},{"d":"Принятие присяги","t":"Как проходит присяга","x":"Инструктор собирает построение на плацу. Из строя поочерёдно вызывается один человек. Форма одежды: принимающий — «Парадный китель с брюками», дающий присягу — «Парадный мундир с брюками». Выбирается в меню F2 → Комплекты одежды → Фракционные. OATH-UNIFORM-GALLERY","r":""},{"d":"Принятие присяги","t":"Вызов из строя","x":"Инструктор: Курсант (Фамилия) Курсант: Я Инструктор: Для принятия торжественной присяги ко мне! Курсант: Есть Курсант выходит из строя, подходит к офицеру по кратчайшей траектории и с последним шагом выполняет воинское приветствие — отдаёт честь. Только после этого докладывает: Товарищ Старший сержант, курсант (Фамилия) для принятия военной присяги прибыл! > Честь отдать обязательно. Доклад без воинского приветствия — нарушение порядка доклада и обращения к старшему, ст. 8 ДУ.","r":""},{"d":"Принятие присяги","t":"Передача текста","x":"Инструктор: /me протянул папку с текстом присяги в руки новобранцу Курсант: /me взял папку с текстом присяги в руки","r":""},{"d":"Принятие присяги","t":"Принятие","x":"Инструктор: Военную присягу принять! Курсант: Есть Курсант поворачивается лицом к строю и произносит текст присяги — уже держа папку в руках: Я, (Фамилия Имя), торжественно присягаю на верность своему Отечеству — Российской Федерации. Клянусь свято соблюдать Конституцию Российской Федерации, строго выполнять требования воинских уставов, приказы командиров и начальников. Клянусь достойно исполнять воинский долг, мужественно защищать свободу, независимость и конституционный строй России, народ и Отечество. Курсант докладывает о принятии: Товарищ Старший сержант, курсант (Фамилия) военную присягу принял!","r":""},{"d":"Принятие присяги","t":"Завершение","x":"Инструктор: /do Присяга успешно принята новобранцем — Имя Фамилия. Поздравляю с принятием присяги, встать в строй Курсант: Есть Курсант возвращается в строй, вызывается следующий.","r":""},{"d":"Принятие присяги","t":"На что смотрят при проверке отчёта","x":"- Присяга отыгрывается, не пишется текстом. Письменная форма — только по веской причине, заранее согласованной с руководством. - Перед тем как встать в строй — снять бронежилет и убрать оружие из-за спины. - На плацу нельзя: телефон, разговоры, приём пищи, курение, неформальный вид — ст. 21 ДУ. Курение — ещё и ст. 12.1. - Имя и фамилия в полной форме: Алексей, а не Лёха.","r":""},{"d":"Система повышения","t":"Общее","x":"# Система повышения курсантов ФСВНГ Путь от 1 ранга до военного билета. Актуальная редакция на 17.09.2026.","r":""},{"d":"Система повышения","t":"Ранг 1 → 2","x":"Пять требований. Выезд за территорию ВЧ — только в сопровождении сотрудников Кадровой службы ФСВНГ, самостоятельный выезд запрещён. # — Требование — Что нужно сделать 1 — Удостоверение — Получить в здании правительства 2 — Лекция по внутренним НПА — Прослушать. Инструктор проводит её разово, сразу по всем шести документам 3 — Лекция-экскурсия по ВЧ — Прослушать 4 — Государственная спец. связь — Присоединиться и получить роль, инструкция ниже 5 — Занятие по физподготовке — 2 скриншота: начало и конец тренировки","r":""},{"d":"Система повышения","t":"Шесть документов лекции по НПА","x":"1. Лекция «Постовая служба» 2. Лекция по субординации 3. Лекция «Строевая подготовка» 4. Дресс-код ФСВНГ 5. Дисциплинарный устав 6. Устав ВС РФ и ФСВНГ Экзамен на этом этапе не сдаётся — он перенесён на этап 2 → 3 и сдаётся один раз по всему материалу целиком, а не по каждому блоку.","r":""},{"d":"Система повышения","t":"Подключение к спец. связи","x":"Четыре шага. Результат — скриншот профиля с ролью Тверской и ником по форме. 1. Присоединиться к спец. связи «Государственные фракции РО»: https://discord.gg/5kTutqS8K 2. Нажать «Получить роль». Получение роли гос. служащего пока недоступно — получаете только Тверской: https://discord.com/channels/1538879177917210668/1538884293592354900/1543186737965309994 3. После этого появится сообщение о получении роли 4. Отредактировать свой ник по форме: Армия | Имя Фамилия | Статик","r":""},{"d":"Система повышения","t":"Что идёт в отчёт","x":"- Скриншот профиля с ролью Тверской - Ник строго по форме Армия | Имя Фамилия | Статик","r":""},{"d":"Система повышения","t":"Ранг 2 → 3","x":"# — Требование — Доказательства 1 — Принятие присяги — 1 скриншот. Отыгровка по процедуре 2 — Стрельбище — 2 скриншота: начало и завершение занятия 3 — Тренировочная площадка — 2 скриншота: начало и конец полосы препятствий 4 — Караул на КПП №1 или КПП №2 Алабино — 1 час — 5 скриншотов каждые 15 минут с докладом в /f 5 — Экзамен по внутренним НПА ФСВНГ — 1 скриншот результата. Один экзамен сразу по всем шести документам","r":""},{"d":"Система повышения","t":"Тайминг караула","x":"Заступили в 16:00 → скриншоты в 16:00, 16:15, 16:30, 16:45, 17:00. Первый — заступление на пост, последний — сдача поста.","r":""},{"d":"Система повышения","t":"После 3 ранга","x":"Выбор подразделения — самостоятельный: ОМОН, РВО, ОСБ или Кадровая служба ФСВНГ.","r":""},{"d":"Система повышения","t":"Порядок подачи","x":"Шаг 1. Отчёт на повышение — подаётся через Google-форму: https://docs.google.com/forms/d/e/1FAIpQLSfbwGdN5GDH8ZOyQWyjBuToUWGr-g03veAsFkhylA7lY7-Dsw/viewform Шаг 2. Запрос на повышение — только после одобрения отчёта, в канал запроса, со ссылкой на одобренный отчёт.","r":""},{"d":"Система повышения","t":"Форма запроса","x":"@Ваш тэг 1. Имя Фамилия Статик 2. Текущий ранг - ранг на который повышаетесь 3. Ссылка на одобренный отчет на повышение @[👮] Инструктор КС ФСВНГ","r":""},{"d":"Система повышения","t":"Пример","x":"@!Комиссар | В. Гуров | 13053 1. Владислав Гуров 13053 2. 2-3 ранг 3. [ссылка на одобренный отчёт] @[👮] Инструктор КС ФСВНГ Заявка не по форме не рассматривается. Последней строкой всегда @[👮] Инструктор КС ФСВНГ.","r":""},{"d":"Система повышения","t":"Военный билет","x":"Подаётся по достижении 6 ранга в #запрос-военных-билетов. После подачи найти старший состав ФСВНГ и попросить выдать билет.","r":""},{"d":"Система повышения","t":"Доказательства","x":"Принимаются фото и видео только с этих сервисов: YouTube, Rutube, Google Drive, Yandex Disk, imgur, Yapx, Prnt, ibb. Фиксация должна исчерпывающе подтверждать выполнение требования. Правила приёма скриншотов уточняются у Кадровой службы.","r":""},{"d":"Частые ошибки в отчётах","t":"Общее","x":"# Частые ошибки при оформлении отчётов Источник: сообщение Нач.КС от 08.09.2026. За эти нарушения отчёт отклоняется.","r":""},{"d":"Частые ошибки в отчётах","t":"1. Отсутствие бодикамеры","x":"- Проект RP → бодикамера обязательна. - На скриншотах должна быть плашка бодикамеры с красным индикатором. - Бодикамера носится везде, кроме построения на плацу. Настройка: F2 → Настройки → Назначение клавиш → Бодикамера → назначить удобную клавишу.","r":""},{"d":"Частые ошибки в отчётах","t":"2. Путаница чатов `/f` и `/fb`","x":"Чат — Тип — Назначение /f — IC (in-character) — Общение по рации в рамках RP. Доклады с караула — сюда /fb — OOC (out-of-character) — Вне роли: реальная жизнь, Discord и т.п.","r":""},{"d":"Частые ошибки в отчётах","t":"3. Редактирование скриншотов — запрещено","x":"Нельзя: - делать частичный скриншот; - обрезать скриншоты; - использовать Photoshop и другие редакторы; - каким-либо образом изменять исходный скриншот. Обнаруженное редактирование = попытка ввести руководство в заблуждение → выговор. > Практический вывод: снимать полный экран целиком, отдавать файл как есть.","r":""},{"d":"Частые ошибки в отчётах","t":"4. Неправильный скриншот Discord","x":"- Нужен скриншот Discord своей фракции, а не общего Discord гос. фракций (State). - На скриншоте обязательно видны роли вашего аккаунта на сервере.","r":""},{"d":"Частые ошибки в отчётах","t":"5. Присяга в письменной форме","x":"- Все действия отыгрываются, проект RP. - Письменная форма — только по веской причине, о которой заранее сообщено руководству.","r":""},{"d":"Частые ошибки в отчётах","t":"6. Некорректные имя и фамилия","x":"Имя и фамилия — в нормальной форме. ❌ Недопустимо — ✅ Правильно Лёха — Алексей Тошик — Антон Данька — Даниил / Данил До исправления ФИО отчёты могут отклоняться.","r":""},{"d":"Частые ошибки в отчётах","t":"7. Заполнение отчёта не по форме","x":"Перед подачей проверить: - [ ] все ли пункты заполнены; - [ ] соблюдена ли последовательность пунктов; - [ ] не изменена ли структура формы; - [ ] соответствуют ли приложенные доказательства указанным пунктам. Перепутанные пункты или изменённая последовательность → отклонение.","r":""},{"d":"Требования к доказательствам","t":"Допустимые хостинги","x":"Фото/видео фиксация принимается только с: Тип — Сервисы Видео — YouTube, Rutube Облако — Google Drive, Yandex Disk Картинки — imgur, Yapx, Prnt, ibb > Фиксация должна иметь исчерпывающие доказательства, подтверждающие то или иное деяние. Правила приёма скриншотов — канал «Требования к скриншотам для отчётов».","r":""},{"d":"Требования к доказательствам","t":"Чек-лист перед загрузкой каждого скриншота","x":"- [ ] Полный экран, без обрезки и редактирования - [ ] Видна плашка бодикамеры с красным индикатором — камера включена везде, кроме построения на плацу - [ ] Виден игровой ник по форме Армия| Имя Фамилия | Статик - [ ] Виден таймер/время, если действие привязано ко времени (караул) - [ ] Доклад написан в /f, а не в /fb - [ ] Ссылка открывается без авторизации (доступ по ссылке для Google/Yandex Disk)","r":""}];
